## CVXPY SOURCE: reductions/eliminate_pwl/canonicalizers/norm_inf_canon.py
## norm_inf(x, axis) = max(abs(x)) -> t where -t <= x <= t


norm_inf_canon <- function(expr, args, solver_context = NULL) {
  x <- args[[1L]]
  axis <- expr@axis
  shape <- .shape(expr)
  bounds <- get_expr_bounds_if_supported(expr, solver_context)
  t <- Variable(shape = shape, bounds = bounds)

  if (is.null(axis)) {
    promoted_t <- cvxr_promote(t, .shape(x))
  } else if (axis == 2L) {
    ones_col <- Constant(matrix(1, nrow = .shape(x)[1L], ncol = 1L))
    t_row <- reshape_expr(t, c(1L, .shape(x)[2L]))
    promoted_t <- ones_col %*% t_row
  } else {
    t_col <- reshape_expr(t, c(.shape(x)[1L], 1L))
    ones_row <- Constant(matrix(1, nrow = 1L, ncol = .shape(x)[2L]))
    promoted_t <- t_col %*% ones_row
  }

  ## CVXPY norm_inf_canon: initialize the epigraph variable for DNLP use.
  if (!is.null(value(expr))) value(t) <- value(expr)
  list(t, list(x <= promoted_t, x + promoted_t >= 0))
}

method(dcp_canonicalize, NormInf) <- norm_inf_canon
method(has_dcp_canon, NormInf) <- function(expr) TRUE
